"""Read-only bridge lifecycle built from the observed JSON-RPC contract."""
from __future__ import annotations

import time
import hashlib
from dataclasses import dataclass

from .provider import Client
from .restream import Go2Rtc

@dataclass
class Camera:
    checkpoint_id: str
    name: str
    channel: str
    stream_name: str
    refreshed_at: float = 0

@dataclass
class Barrier:
    barrier_id: str
    name: str
    acs_id: str

class Bridge:
    def __init__(self, client: Client, restream: Go2Rtc, refresh_seconds: int = 45):
        self.client, self.restream, self.refresh_seconds = client, restream, refresh_seconds
        self.cameras: dict[str, Camera] = {}
        self.barriers: dict[str, Barrier] = {}

    def authenticate(self, phone: str, object_id: str, code: str) -> None:
        self.client.authorize(phone, object_id, code)

    def discover(self) -> list[Camera]:
        cameras: dict[str, Camera] = {}
        barriers: dict[str, Barrier] = {}
        for obj in self.client.inventory():
            for checkpoint in self.client.checkpoints(str(obj['id'])):
                channel = checkpoint.get('channel')
                checkpoint_id = str(checkpoint['id'])
                name = str(checkpoint.get('name','Checkpoint'))
                if channel:
                    cameras[checkpoint_id] = Camera(checkpoint_id, name, str(channel), self.restream.stable_name(checkpoint_id))
                acs_id = checkpoint.get('acsId')
                if acs_id:
                    barrier_id = 'md_parking_access_' + hashlib.sha256(checkpoint_id.encode()).hexdigest()[:12]
                    barriers[barrier_id] = Barrier(barrier_id, name, str(acs_id))
        self.cameras = cameras
        self.barriers = barriers
        return list(cameras.values())

    def open_barrier(self, barrier_id: str) -> object:
        barrier = self.barriers.get(barrier_id)
        if barrier is None: raise KeyError('unknown barrier')
        return self.client.access(barrier.acs_id)

    def refresh(self, checkpoint_id: str) -> Camera:
        camera = self.cameras[checkpoint_id]
        source = self.client.stream(camera.channel)
        self.restream.replace_source(camera.stream_name, source)
        camera.refreshed_at = time.time()
        return camera

    def refresh_due(self) -> list[Camera]:
        now=time.time(); updated=[]; first_failure=None
        for camera in self.cameras.values():
            if now-camera.refreshed_at >= self.refresh_seconds:
                try:
                    updated.append(self.refresh(camera.checkpoint_id))
                except Exception as exc:
                    # One unavailable camera must not prevent the other
                    # sources from rotating. Keep the failed camera due so the
                    # worker retries it on its next pass.
                    if first_failure is None: first_failure=exc
        if first_failure is not None: raise first_failure
        return updated
